var visibleText = "";

Array.from(document.querySelectorAll('*'))
  .filter(element => {
    var computedStyle = window.getComputedStyle(element);
    return (
      element.offsetHeight > 0 &&
      element.offsetWidth > 0 &&
      computedStyle.display !== 'none' &&
      computedStyle.visibility !== 'hidden' &&
      element.tagName !== 'SCRIPT' &&
      element.tagName !== 'STYLE'
    );
  })
  .forEach(element => {
    var textContent = element.innerText.trim();
    if (textContent !== '' && !visibleText) {
      visibleText = textContent; // Store only the first visible text
    }
  });

var interactableElements = document.querySelectorAll('input:not([type="hidden"]), button, textarea, select, a');

var output = "";
var count = 0;

var firstElements = {};

for (var index = 0; index < interactableElements.length; ++index) {
  var element = interactableElements[index];
  var elementId = element.id;
  var elementType = element.type;
  var elementClass = element.className;

  if (!element.hidden && elementType) {
    count++;
    if (elementType === "submit" || elementType === "button") {
      if (!isExcluded(element)) {
        element.addEventListener("click", function() {
          console.log(`Clicked element with ID: ${elementId}`);
        });
        element.click();
      }
    } else {
      var tagName = element.tagName.toLowerCase();
      if (!(tagName in firstElements) && !isExcluded(element)) {
        firstElements[tagName] = true;
        element.click();
      }
    }
    var listItem = `${count}. Element ID: ${elementId}, Input Type: ${elementType}, Class: ${elementClass}`;

    var associatedLabel = document.querySelector(`label[for="${elementId}"]`);
    if (associatedLabel) {
      var labelText = associatedLabel.innerText.trim();
      listItem += `, Label Text: ${labelText}`;
    }

    output += listItem + "\n";
  }
}

function isExcluded(element) {
  var excludedKeywords = ['back', 'prev', 'previous'];
  var elementId = element.id;
  var elementType = element.type;
  var elementClass = element.className;
  return excludedKeywords.some(keyword => {
    return elementId.includes(keyword) || elementClass.includes(keyword) || element.getAttributeNames().some(attrName => {
      return element.getAttribute(attrName).toLowerCase().includes(keyword);
    });
  }) || elementType === "hidden";
}

