async function addUnitsToCamping(camping, units, res) {
  const session = await mongoose.startSession();
  session.startTransaction();

  try {
    const campingUnits = [];
    for(const unit of units) {
      if (unit._id.startsWith('new')) {
        delete unit._id;
      }
      const campingUnit = new CampingUnit(unit);
      campingUnit.camping = camping._id;
      await campingUnit.validate();
      campingUnits.push(campingUnit);
    }
    await CampingUnit.insertMany(campingUnits, { session });
    await session.commitTransaction();
  } catch (error) {
    await session.abortTransaction();
    res.status(500).json({
      error: 'invalid_unit',
      errors: error.errors,
    });
  } finally {
    session.endSession();
  }
}

