using UnityEngine;

public class ColliderChecker : MonoBehaviour
{
    [SerializeField] private SphereCollider sphereCollider;
    [SerializeField] private List<GameObject> objectsInRange = new List<GameObject>();

    public List<GameObject> ObjectsInRange => objectsInRange;

    private void Awake()
    {
        // Если ссылка на компонент SphereCollider не установлена в инспекторе, пробуем найти его на этом объекте
        if (!sphereCollider) sphereCollider = GetComponent<SphereCollider>();
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.gameObject != gameObject && sphereCollider.bounds.Contains(other.transform.position))
        {
            if (!objectsInRange.Contains(other.gameObject))
            {
                objectsInRange.Add(other.gameObject);
            }
        }
    }

    private void OnTriggerExit(Collider other)
    {
        if (other.gameObject != gameObject)
        {
            objectsInRange.Remove(other.gameObject);
        }
    }

    private void OnDrawGizmosSelected()
    {
        if (objectsInRange != null)
        {
            Gizmos.color = Color.green;
            foreach (var obj in objectsInRange)
            {
                Gizmos.DrawLine(transform.position, obj.transform.position);
            }
        }
    }
}

