function createReleaseBox(release) {
  const box = document.createElement('div');
  const boxHeader = document.createElement('h2');
  const boxBody = document.createElement('div');

  box.style.opacity = 0;
  box.classList.add('box');
  boxHeader.classList.add('box-header');
  boxBody.classList.add('box-body');

  boxHeader.innerText = release['name'];
  boxBody.innerHTML = marked.parse(release['body']);

  box.appendChild(boxHeader);
  box.appendChild(boxBody);

  return box;
}

function animateOpacity(element) {
  let opacity = 0;

  function step() {
    opacity += 0.0125;
    element.style.opacity = opacity;

    if (opacity < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

