List<List<int>> subsequenceGenerator(int seq, int sub) {
  List<List<int>> cache = [];
  List<List<int>> result = [];

  for (int i = 0; i < seq; i++) {
    List<List<int>> newSub = [];

    // Adding the current element to the existing subsequences in the cache
    for (List<int> subList in cache) {
      if (subList.length < sub) {
        newSub.add([...subList, i]);
      }
    }

    // Adding the current element as a new subsequence
    newSub.add([i]);

    // Adding new subsequences to the result list
    for (List<int> subList in newSub) {
      result.add(subList);
    }

    // Caching the new subsequences
    cache.addAll(newSub);
  }

  return result..retainWhere((e) => e.length == sub);
}

