export function splitIntNumberStrToArray(value, separator = ',', maxLen, name = '', vueInstance) {
  const reg = /\D/
  let list = []
  if (value) {
    list = value
      .split(separator)
      .map((s) => s.trim())
      .filter((s) => s)
    const existNaN = list.some((v) => reg.test(v))
    if (existNaN) {
