throw new Error(“You don’t have that card in your hand.”);
}

if (!card.isPlayable(targetPlayer, this.currentPlayer, this.playedCards)) {
throw new Error(“You can’t play that card right now.”);
}

card.play(this.currentPlayer, targetPlayer);
this.playedCards.push(card);
this.currentPlayer.removeCard(card);
}

playTurn(targetPlayerIndex) {
const targetPlayer = this.players[targetPlayerIndex];
const playableCards = this.currentPlayer.hand.filter(
(card) => card.isPlayable(targetPlayer, this.currentPlayer, this.playedCards)
);

