throw new Error(“You don’t have any playable cards.”);
}

const chosenCardIndex = Math.floor(Math.random() * playableCards.length);
const chosenCard = playableCards[chosenCardIndex];

this.playCard(chosenCard, targetPlayer);
this.currentPlayerIndex = (this.currentPlayerIndex + 1) % this.players.length;
}

getValidTargets(card) {
return this.players.filter(
(player) => player !== this.currentPlayer && card.isPlayable(player, this.currentPlayer, this.playedCards)
);
}
