function rotateX(angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return [
    [1, 0, 0],
    [0, c, -s],
    [0, s, c],
  ];
}

function rotateY(angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return [
    [c, 0, s],
    [0, 1, 0],
    [-s, 0, c],
  ];
}

function rotateZ(angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return [
    [c, -s, 0],
    [s, c, 0],
    [0, 0, 1],
  ];
}

function project(vertex, scale, offsetX, offsetY, zoom) {
  const [x, y, z] = vertex;
  return [
    ((x * scale) / (zoom + z) + offsetX),
    ((y * scale) / (zoom + z) + offsetY),
  ];
}

function transform(vertex, rotationMatrix) {
  const [x, y, z] = vertex;
  const [rowX, rowY, rowZ] = rotationMatrix;
  return [
    x * rowX[0] + y * rowX[1] + z * rowX[2],
    x * rowY[0] + y * rowY[1] + z * rowY[2],
    x * rowZ[0] + y * rowZ[1] + z * rowZ[2],
  ];
}

let angleX = 0;
let angleY = 0;
let angleZ = 0;

function render() {
  ctx.fillStyle = '#FFF';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const rotX = rotateX(angleX);
  const rotY = rotateY(angleY);
  const rotZ = rotateZ(angleZ);

  const transformedVertices = vertices.map(vertex => {
    const cx = vertex[0] - 0.5;
    const cy = vertex[1] - 0.5;
    const cz = vertex[2] - 0.5;

    const rotated = transform(transform(transform([cx, cy, cz], rotX), rotY), rotZ);

    return [
      rotated[0] + 0.5,
      rotated[1] + 0.5,
      rotated[2] + 0.5,
    ];
  });

  const scale = Math.min(canvas.width, canvas.height) / 4;
  const offsetX = canvas.width / 2;
  const offsetY = canvas.height / 2;
  const zoom = 1;

  const projectedVertices = transformedVertices.map(vertex => project(vertex, scale, offsetX, offsetY, zoom));

  ctx.strokeStyle = '#000';
  ctx.beginPath();

  for (let edge of edges) {
    const [a, b] = edge;
    const [x1, y1] = projectedVertices[a];
    const [x2, y2] = projectedVertices[b];

    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
  }

  ctx.stroke();

  angleX += 0.01;
  angleY += 0.013;
  angleZ += 0.007;

  requestAnimationFrame(render);
}

